<template><div class="app-container"><el-form :inline="true" size="small" :model="query"><el-form-item label="手机号"><el-input v-model="query.phone" clearable/></el-form-item><el-form-item label="昵称"><el-input v-model="query.nickname" clearable @keyup.enter.native="load"/></el-form-item><el-form-item><el-button type="primary" icon="el-icon-search" size="mini" @click="load">查询</el-button></el-form-item></el-form><el-table v-loading="loading" :data="list"><el-table-column prop="memberId" label="会员ID" width="90"/><el-table-column prop="phone" label="手机号" width="130"/><el-table-column prop="nickname" label="昵称"/><el-table-column prop="registerSource" label="注册来源" width="100"/><el-table-column prop="lastLoginIp" label="最近登录IP"/><el-table-column prop="lastLoginTime" label="最近登录时间" width="165"/><el-table-column label="状态" width="90"><template slot-scope="s"><el-tag :type="s.row.status === '0' ? 'success' : 'info'">{{ s.row.status === '0' ? '正常' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template slot-scope="s"><el-button type="text" size="mini" @click="openEdit(s.row)" v-hasPermi="['mall:member:edit']">修改</el-button></template></el-table-column></el-table><pagination v-show="total > 0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load"/><el-dialog title="修改会员" :visible.sync="dialog" width="420px"><el-form :model="form" label-width="80px"><el-form-item label="昵称"><el-input v-model="form.nickname"/></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio label="0">正常</el-radio><el-radio label="1">停用</el-radio></el-radio-group></el-form-item></el-form><div slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">确定</el-button></div></el-dialog></div></template>
<script>import { listMembers, updateMember } from '@/api/mall/member'
export default { name: 'MallMember', data () { return { loading: false, list: [], total: 0, query: { pageNum: 1, pageSize: 10 }, dialog: false, form: {} } }, created () { this.load() }, methods: { load () { this.loading = true; listMembers(this.query).then(r => { this.list = r.rows || (r.data && r.data.rows) || []; this.total = r.total || (r.data && r.data.total) || this.list.length }).finally(() => { this.loading = false }) }, openEdit (r) { this.form = Object.assign({}, r); this.dialog = true }, save () { updateMember(this.form).then(() => { this.$modal.msgSuccess('保存成功'); this.dialog = false; this.load() }) } } }</script>
